func hasFreeLine(lines []QuoteLineView) bool {
	for _, l := range lines {
		if l.IsFree {
			return true
		}
	}
	return false
}

// costosPath is where an issued quote's free-line costs are updated.
func costosPath(folio string) string {
	return "/cotizaciones/" + folio + "/costos"
}

